// Verifies Retell's x-retell-signature (v=<ms>,d=<hex HMAC-SHA256(rawBody + v)>)
// and passes on the parsed payload. Throws on anything invalid, so the error
// workflow reports it. Self-hosted n8n needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');

// Preferred: n8n Variable RETELL_WEBHOOK_KEY. Without Variables on your plan,
// paste the Retell API key that has the webhook badge here instead.
const RETELL_WEBHOOK_KEY_CONSTANT = 'PASTE_RETELL_WEBHOOK_KEY_HERE';
const MAX_AGE_MS = 5 * 60 * 1000;

let key = '';
try {
  key = ($vars && $vars.RETELL_WEBHOOK_KEY) || '';
} catch (e) {
  // Variables are not available on this plan
}
if (!key && !RETELL_WEBHOOK_KEY_CONSTANT.startsWith('PASTE_')) key = RETELL_WEBHOOK_KEY_CONSTANT;
if (!key) {
  throw new Error('No Retell webhook key: set the n8n Variable RETELL_WEBHOOK_KEY or the constant in "Verify signature".');
}

const item = $input.first();
if (!item.binary || !item.binary.data) {
  throw new Error('No raw body: turn on the "Raw Body" option of the "Retell webhook" node.');
}
const h = typeof helpers !== 'undefined' && helpers ? helpers : this && this.helpers;
const raw = h && typeof h.getBinaryDataBuffer === 'function'
  ? (await h.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : Buffer.from(item.binary.data.data, 'base64').toString('utf8');

const headers = item.json.headers || {};
const match = /^v=(\d+),d=([0-9a-f]+)$/i.exec(String(headers['x-retell-signature'] || '').trim());
if (!match) throw new Error('Missing or malformed x-retell-signature header');
const [, ts, digest] = match;
if (Math.abs(Date.now() - Number(ts)) > MAX_AGE_MS) {
  throw new Error('Stale Retell signature (more than 5 minutes off)');
}
const expected = crypto.createHmac('sha256', key).update(raw + ts).digest();
const given = Buffer.from(digest, 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
  throw new Error('Invalid signature: not from Retell, or the webhook key is wrong');
}

return [{ json: JSON.parse(raw) }];

// Turns a verified call_analyzed payload into one Telegram HTML message.
// Missing values print as "—"; nothing is filled in.

// ---- config ----------------------------------------------------------------
const TIME_ZONE = 'America/New_York'; // company time zone
const MAX_LEN = 4096; // Telegram message limit
const FIELD_MAX = 400; // characters per field before trimming
// ----------------------------------------------------------------------------

const call = $input.first().json.call || {};

// Retell retries webhooks; send one alert per call.
const store = $getWorkflowStaticData('global');
const alerted = (store.alertedCalls = store.alertedCalls || {});
const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;
for (const id of Object.keys(alerted)) if (alerted[id] < cutoff) delete alerted[id];
if (call.call_id && alerted[call.call_id]) return [];
if (call.call_id) alerted[call.call_id] = Date.now();

const analysis = call.call_analysis || {};
const d = analysis.custom_analysis_data || {};

const DASH = '—';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const has = (v) => v !== undefined && v !== null && String(v).trim() !== '';
const cut = (s, n) => (s.length <= n ? s : n <= 1 ? '…' : `${s.slice(0, n - 1)}…`);
const val = (v, n = FIELD_MAX) => (has(v) ? esc(cut(String(v).trim(), n)) : DASH);
const yesNo = (v) => (v === true ? 'yes' : v === false ? 'no' : DASH);

const durationMs = has(call.duration_ms)
  ? Number(call.duration_ms)
  : has(call.start_timestamp) && has(call.end_timestamp) ? call.end_timestamp - call.start_timestamp : NaN;
const duration = Number.isFinite(durationMs)
  ? `${Math.floor(Math.round(durationMs / 1000) / 60)}m ${Math.round(durationMs / 1000) % 60}s`
  : DASH;
const started = has(call.start_timestamp) && Number.isFinite(new Date(Number(call.start_timestamp)).getTime())
  ? new Date(Number(call.start_timestamp)).toLocaleString('en-US', {
    timeZone: TIME_ZONE, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit',
  })
  : DASH;
const recording = has(call.recording_url) ? `<a href="${esc(call.recording_url)}">Listen</a>` : DASH;

const type = d.caller_type;
const outcome = d.outcome;
let template;
if (type === 'spam') template = 'spam';
else if (type === 'warranty_company') template = 'warranty_company_message';
else if (outcome === 'booked') template = type === 'warranty_customer' ? 'warranty_booking' : 'standard_booking';
else if (['fee_declined', 'dropped', 'incomplete'].includes(outcome) && type !== 'other') template = 'no_booking';
else template = 'other';

const NO_BOOKING_REASON = { fee_declined: 'fee declined', dropped: 'caller hung up', incomplete: 'intake not finished' };

function render(summaryMax) {
  const summary = has(analysis.call_summary) ? esc(cut(String(analysis.call_summary).trim(), summaryMax)) : DASH;
  if (template === 'spam') {
    const oneLine = has(analysis.call_summary)
      ? esc(cut(String(analysis.call_summary).replace(/\s+/g, ' ').trim(), Math.min(summaryMax, 200)))
      : DASH;
    return `🚫 Spam from ${val(call.from_number)} · ${duration} · ${oneLine}`;
  }
  const footer = [
    `Caller ID: ${val(call.from_number)}`,
    `Time: ${started} · Duration: ${duration}`,
    `Summary: ${summary}`,
    `Recording: ${recording}`,
  ];
  const job = [
    `Name: ${val(d.caller_name)}`,
    `Callback: ${val(d.callback_number)}`,
    `Address: ${val(d.service_address)}`,
    `Appliance: ${val(d.appliance)} · Brand: ${val(d.brand)}`,
    `Issue: ${val(d.issue)}`,
    `Notes: ${val(d.notes)}`,
  ];
  let head;
  if (template === 'standard_booking') {
    head = ['🔧 <b>New booking: standard job</b>', `$99 fee accepted: ${yesNo(d.fee_accepted)}`, ...job];
  } else if (template === 'warranty_booking') {
    head = ['🛡️ <b>New booking: warranty job</b> (no fee)', `Warranty brand: ${val(d.brand)}`, ...job];
  } else if (template === 'warranty_company_message') {
    head = [
      '📨 <b>Message from a warranty company</b>',
      `Company: ${val(d.warranty_company)}`,
      `Name: ${val(d.caller_name)}`,
      `Callback: ${val(d.callback_number)}`,
      `Job: ${val(d.job_details)}`,
      `Notes: ${val(d.notes)}`,
    ];
  } else if (template === 'no_booking') {
    head = [`⚠️ <b>No booking</b> (${NO_BOOKING_REASON[outcome]})`, ...job];
  } else {
    head = [
      '📞 <b>Callback request / other call</b>',
      `Name: ${val(d.caller_name)}`,
      `Callback: ${val(d.callback_number)}`,
      `Issue: ${val(d.issue)}`,
      `Notes: ${val(d.notes)}`,
    ];
  }
  return [...head, '', ...footer].join('\n');
}

let summaryMax = 3000;
let text = render(summaryMax);
while (text.length > MAX_LEN && summaryMax > 0) {
  summaryMax = Math.max(0, summaryMax - (text.length - MAX_LEN) - 20);
  text = render(summaryMax);
}
if (text.length > MAX_LEN) text = text.slice(0, text.lastIndexOf('\n', MAX_LEN)); // whole lines keep tags balanced

return [{ json: { text, silent: template === 'spam', template, call_id: call.call_id || null } }];
